{"cards": [{"node_code": "N_ed24b8a78088d545", "definition": "研究材料宏观及微观区域化学元素种类、含量及物相组成的检测与分析技术，涵盖光谱、色谱及衍射等定量定性方法。", "boundary": "聚焦于材料“由什么组成”及“存在哪些相”的信息获取。包括整体成分分析、微区成分探测及物相鉴定。侧重于化学计量与相态识别，不涉及微观形貌的几何特征描述（如晶粒尺寸、形状）或三维空间结构重建，也不涉及基于成分数据的性能预测或失效机理推导。", "includes": ["材料整体及微区化学成分定量与定性分析（如XRF, EDS, ICP）", "物相鉴定、相图分析及相变产物识别（如XRD, EBSD相分析）", "杂质元素检测及化学均匀性评估"], "excludes": ["微观组织形貌、晶粒尺寸及取向分布的几何表征（归显微组织与晶体学表征）", "孔隙、裂纹等缺陷的空间分布及三维结构重建（归孔隙、界面与三维结构表征）"], "sibling_distinctions": [{"other_code": "N_705c3cc800fbe1ad", "rule": "本节点关注“是什么元素/相”，侧重化学组成与相态；兄弟节点关注“长什么样/怎么排列”，侧重形貌、尺寸与晶体取向。"}, {"other_code": "N_8698163a8c5900ce", "rule": "本节点关注成分与相的分布；兄弟节点关注缺陷（孔隙、界面）的几何形态、空间位置及三维连通性。"}], "cross_boundary_rule": "若分析重点在于确定某区域的元素含量或相种类，归本节点；若重点在于观察该相的形貌特征、晶粒边界或三维空间分布，归显微组织或三维结构节点。"}, {"node_code": "N_705c3cc800fbe1ad", "definition": "研究材料微观组织形貌、晶粒特征、相分布及晶体取向关系的显微观察与晶体学分析技术。", "boundary": "聚焦于材料微观结构的几何特征与晶体学信息。包括光学/电子显微观察、晶粒尺寸统计、相形貌描述、织构分析及位错/亚结构观察。侧重于“结构长什么样”及“晶体如何排列”，不涉及元素化学组成的定量分析（除非作为相识别的辅助），也不涉及宏观性能测试或三维缺陷网络重建。", "includes": ["光学、扫描/透射电子显微镜下的组织形貌观察与图像分析", "晶粒尺寸、形状、相分布及界面特征的定量统计", "晶体取向、织构（Texture）及位错/亚结构的晶体学表征"], "excludes": ["材料整体或微区化学成分的元素定量分析（归化学成分与物相分析）", "孔隙、裂纹等缺陷的三维空间分布及体积分数重建（归孔隙、界面与三维结构表征）"], "sibling_distinctions": [{"other_code": "N_ed24b8a78088d545", "rule": "本节点关注形貌、尺寸与取向等几何/晶体学特征；兄弟节点关注元素种类与含量等化学组成信息。"}, {"other_code": "N_8698163a8c5900ce", "rule": "本节点侧重二维或局部三维的晶体学/形貌特征；兄弟节点侧重孔隙、界面等缺陷的三维空间拓扑结构与体积量化。"}], "cross_boundary_rule": "若研究重点在于晶粒取向、织构或相的形貌特征，归本节点；若重点在于孔隙率、裂纹三维网络或界面面积密度的空间重建，归三维结构节点。"}, {"node_code": "N_8698163a8c5900ce", "definition": "研究材料内部孔隙、裂纹、夹杂等缺陷及相界面的三维空间分布、形态特征及体积量化表征技术。", "boundary": "聚焦于材料内部非均匀结构（特别是缺陷与界面）的三维空间信息获取。包括断层扫描（CT）、聚焦离子束（FIB）三维重构、界面面积/曲率分析及缺陷体积分数统计。侧重于“空间分布”与“三维拓扑”，不涉及元素化学分析或晶体取向分析，也不涉及基于缺陷的力学性能预测。", "includes": ["孔隙、气孔、裂纹、夹杂等缺陷的三维成像与空间分布分析", "相界面、晶界网络的三维重构、面积密度及曲率统计", "基于三维重构的缺陷体积分数、连通性及形态参数量化"], "excludes": ["材料化学成分或物相种类的鉴定（归化学成分与物相分析）", "晶粒取向、织构等晶体学信息的分析（归显微组织与晶体学表征）"], "sibling_distinctions": [{"other_code": "N_ed24b8a78088d545", "rule": "本节点关注缺陷/界面的三维空间几何特征；兄弟节点关注化学组成与相态。"}, {"other_code": "N_705c3cc800fbe1ad", "rule": "本节点侧重三维空间拓扑与体积量化；兄弟节点侧重二维形貌或晶体取向/织构分析。"}], "cross_boundary_rule": "若研究重点在于缺陷的三维空间分布、体积分数或界面网络拓扑，归本节点；若重点在于缺陷处的成分偏析或晶粒取向，归成分或晶体学节点。"}]}
